import XCTest
@testable import AtlasCore

/// The finish line: a proof GENERATED BY THE PYTHON BACKEND verifies on the phone (Swift/blst),
/// byte-for-byte. The Fiat-Shamir challenge hashes only G1/G2 elements + scalars (all cross-language
/// identical), so the two implementations agree with no shared field representation.
final class AnonCredInteropTests: XCTestCase {
    private func g1(_ h: String) -> G1 { G1.deserialize(Array(hex: h))! }
    private func g2(_ h: String) -> G2 { G2.deserialize(Array(hex: h))! }
    private func fr(_ h: String) -> Fr { Fr(reducingBE: Array(hex: h)) }

    func testVerifyPythonGeneratedProof() {
        // vector generated by backend/atlas/realid/anon_accreditation.py (claim "work:BSc", nonce "nonce")
        let XT = ""
        let Y0 = ""
        let Y1 = ""
        let S1 = "0429d163b59d979158a4cf19445421a1fe524f2f04222c4e71bc1dc2f05b19657f41f341df5b72147701b46ef67e7c3c1774a04f58a527bdc7e7d4b7887db56f0403dbf536386c76574ce97f4a0649795cabf25c487fb49ab6ccea22a716bc4e"
        let S2 = "0e6f340c8a093042489fb5af36c27b2672b21ccff4935208702a1777ae83daa2c18184635ccfa5de3c121f2ded142614036d30ece1dd0c99d67c6b80e9b73e36a73327b1ba176c6f69aee9c24b28780663f6dd20190a364bf11befb2d35ea4dc"
        let RC = ""
        let Z0 = "6ce474ab5b4d0e42fe8cb7cfb0cfc72c59e0f7adc6a5ccfa6f53bcbb17051d30"
        let ZT = "453e95ab29c2d1d18cb51181def260f180b10d79101ab41bafbdd977bc36e95e"
        let CH = "1cd72069823d54514e289f0a8be9144ef6572ea9d2295d6931e43ce77521184d"

        let pub = PS.PublicKey(Xt: g2(XT), Yt: [g2(Y0), g2(Y1)], Yg1: [], n: 2)
        let proof = PS.Proof(s1: g1(S1), s2: g1(S2), commitment: g2(RC), reveal: [0],
                             revealedVals: [Fr.msg("work:BSc")], responses: [fr(Z0), fr(ZT)], challenge: fr(CH))
        XCTAssertTrue(AnonCred.verify(pub, proof, claim: "work:BSc", nonce: Data("nonce".utf8)))
        // sanity: a different claim must not verify the same proof
        XCTAssertFalse(AnonCred.verify(pub, proof, claim: "work:MSc", nonce: Data("nonce".utf8)))
    }

    /// The full revocable showing (credential AND non-revoked, handle-bound) generated by the Python
    /// backend (anon_revocable.py) verifies here on Swift/blst.
    func testVerifyPythonRevocableProof() {
        let XT = ""
        let Y0 = ""
        let Y1 = ""
        let Y2 = ""
        let AP = ""
        let AC = "062311d1753139ed0a1ddc79d91845425a912866da3cfef96d7e572a9ba9290bf6417c0054c48ec46064f4117d83ceb916e2491258d45ab1d06142a968a0d9dfb17d18c961e7c30acc7ab2218538d0e3d8470e9e4b42f4cd7c1faa982ea88091"
        let S1 = "0290071c0888801aa9354d57a5ec5c4adcd39cfb8c5bb29a51dd95acbe64bc38beb705824048c189606241ac6e02ade90bb5613265c951c16750f95f18f3a0553374ca4d88913d21d42a13929ea742f79aedb5528ec2330c6de9408b9708016b"
        let S2 = "085137725d32b09dcf7e85937a42328095d75c8db7c5cd2eae9fb04d067e859d7f2ff2bace5c813c667cadf49d1a9cdb01e7d59f2112928e9845812b87f3b14e558891400abd149b002cd46ea11d464d07002fc0b4dd5b0999cdc18118bc6b2b"
        let WB = "07cfa0a197a0d99ccaeba606cee60d38559ba79c2342e8fa31b7c33c150fc5d51e01d879a648df12292b944cf08a10b90b5e624e9596518af6249b3d2188abb8ae0cb82b26ec01bdd594fab86489cfcdc8d94610833b5abad22bb0e0a75b58e4"
        let RP = ""
        let RM = "080c516b3d01e573bf2574d7fb8c95c65bbd2cd0feaabd3ff1dc47177e9b6a752edac61769ab4dc624e6201fd864925f10652edac5e3986ba740e80ff1729df2a7fa213c15fc6644c8b50c67502465fafa7f6fb4c3c75fc137b79ccf6af16e9d"
        let C = "370a938ed9631abe514023953bbe4068d413403b382f0bec00047c7cc744d3c4"
        let ZM = "69f3f3363e45705c540df241310164487043812e7000d79b9a96d5c9de6883f1"
        let ZH = "20d9996e561fdd3d8312a09db6fbd68a074c917c0168228cc2a6b57b18ec0372"
        let ZT = "3c87018ee562e982bd0924793c906694939b6acba147b061aa29e8f1bdf6ded9"
        let ZR = "64f64c85e1927a0dc57bb234443c47a3b8ac5c8c649fb19e0e7fe58b5132c57f"

        let pub = PS.PublicKey(Xt: g2(XT), Yt: [g2(Y0), g2(Y1), g2(Y2)], Yg1: [], n: 3)
        let proof = Revocable.Proof(s1: g1(S1), s2: g1(S2), wbar: g1(WB), rPs: g2(RP), rMem: g1(RM),
                                    c: fr(C), zMs: fr(ZM), zHandle: fr(ZH), zT: fr(ZT), zRho: fr(ZR))
        XCTAssertTrue(Revocable.verify(pub, accPub: g2(AP), accumulator: g1(AC), proof,
                                       claim: "work:BSc", nonce: Data("nonce".utf8)))
        XCTAssertFalse(Revocable.verify(pub, accPub: g2(AP), accumulator: g1(AC), proof,
                                        claim: "work:MSc", nonce: Data("nonce".utf8)))
    }
}

private extension Array where Element == UInt8 {
    init(hex: String) {
        var out = [UInt8](); out.reserveCapacity(hex.count / 2)
        var i = hex.startIndex
        while i < hex.endIndex {
            let j = hex.index(i, offsetBy: 2)
            out.append(UInt8(hex[i..<j], radix: 16)!)
            i = j
        }
        self = out
    }
}
